from icontract import ensure, snapshot

def check_bipartite(adj_list):
    """
    Determine if the given graph is bipartite.

    Time complexity is O(|E|)
    Space complexity is O(|V|)
    """
    n = len(adj_list)
    colors = [-1] * n  # -1: uncolored, 0: color 0, 1: color 1

    for start_node in range(n):
        if colors[start_node] == -1:
            queue = [start_node]
            colors[start_node] = 0

            while queue:
                u = queue.pop(0)

                for v in adj_list[u]:
                    if colors[v] == -1:
                        colors[v] = 1 - colors[u]
                        queue.append(v)
                    elif colors[v] == colors[u]:
                        return False

    return True

